172: function drawMapThumb(canvasEl, map) {
173:   const w = 560;
174:   const h = 240;
175:   canvasEl.width = w;
176:   canvasEl.height = h;
177:   const ctx = canvasEl.getContext('2d');
178:   const t = THEMES[map.theme] || THEMES.sunrise;
179:   const bg = ctx.createLinearGradient(0, 0, w, h);
180:   bg.addColorStop(0, t.skyTop);
181:   bg.addColorStop(0.58, t.skyMid);
182:   bg.addColorStop(1, t.skyBottom);
183:   ctx.fillStyle = bg;
184:   ctx.fillRect(0, 0, w, h);
185: 
186:   ctx.globalAlpha = 0.18;
187:   ctx.strokeStyle = t.top;
188:   ctx.lineWidth = 1;
189:   for (let x = 0; x < w; x += 28) {
190:     ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
191:     ctx.beginPath(); ctx.moveTo(0, x / 2); ctx.lineTo(w, x / 2); ctx.stroke();
192:   }
193:   ctx.globalAlpha = 1;
194: 
195:   const b = courseBounds(map.pieces);
196:   const pad = 26;
197:   const spanX = Math.max(1, b.maxX - b.minX + 1);
198:   const spanZ = Math.max(1, b.maxZ - b.minZ + 1);
199:   const scale = Math.min((w - pad * 2) / spanX, (h - pad * 2) / spanZ);
200:   const ox = (w - spanX * scale) / 2 - b.minX * scale + scale / 2;
201:   const oz = (h - spanZ * scale) / 2 - b.minZ * scale + scale / 2;
202:   const px = (x) => ox + x * scale;
203:   const pz = (z) => oz + z * scale;
204:   const size = Math.max(5, scale * 0.86);
205: 
206:   // dashed route
207:   if (map.pieces.length > 1) {
208:     ctx.save();
209:     ctx.setLineDash([4, 8]);
210:     ctx.strokeStyle = 'rgba(255,255,255,.28)';
211:     ctx.lineWidth = 2;
212:     ctx.beginPath();
213:     map.pieces.forEach((p, i) => {
214:       const x = px(p.x);
215:       const y = pz(p.z);
216:       if (i === 0) ctx.moveTo(x, y);
217:       else ctx.lineTo(x, y);
218:     });
219:     ctx.stroke();
220:     ctx.restore();
221:   }
222: 
223:   const sorted = [...map.pieces].sort((a, b2) => a.l - b2.l);
224:   for (const p of sorted) {
225:     const x = px(p.x);
226:     const y = pz(p.z);
227:     const s = size;
228:     const levelLift = p.l * 1.5;
229:     ctx.fillStyle = 'rgba(0,0,0,.26)';
230:     ctx.beginPath();
231:     ctx.roundRect(x - s / 2 + 3, y - s / 2 + 4, s, s, 4);
232:     ctx.fill();
233: 
234:     if (p.t === 'ramp') {
235:       ctx.fillStyle = t.bodySide;
236:       ctx.beginPath();
237:       ctx.moveTo(x - s / 2, y + s / 2);
238:       ctx.lineTo(x + s / 2, y + s / 2);
239:       ctx.lineTo(x + s / 2, y - s / 2);
240:       ctx.closePath();
241:       ctx.fill();
242:       ctx.strokeStyle = t.accent;
243:       ctx.lineWidth = 2;
244:       ctx.stroke();
245:     } else if (p.t === 'beam') {
246:       ctx.fillStyle = t.top;
247:       const narrow = s * 0.34;
248:       const vertical = p.r % 2 === 0;
249:       ctx.beginPath();
250:       ctx.roundRect(x - (vertical ? narrow : s) / 2, y - (vertical ? s : narrow) / 2, vertical ? narrow : s, vertical ? s : narrow, 3);
251:       ctx.fill();
252:     } else if (p.t === 'spinner') {
253:       ctx.fillStyle = t.body;
254:       ctx.beginPath(); ctx.roundRect(x - s / 2, y - s / 2, s, s, 4); ctx.fill();
255:       ctx.strokeStyle = t.accent2;
256:       ctx.lineWidth = 3.5;
257:       ctx.beginPath(); ctx.moveTo(x - s * 0.55, y + s * 0.2); ctx.lineTo(x + s * 0.55, y - s * 0.2); ctx.stroke();
258:       ctx.fillStyle = t.accent2;
259:       ctx.beginPath(); ctx.arc(x, y, 2.4, 0, Math.PI * 2); ctx.fill();
260:     } else if (p.t === 'mover') {
261:       ctx.fillStyle = t.top;
262:       ctx.beginPath(); ctx.roundRect(x - s / 2, y - s / 2, s, s, 4); ctx.fill();
263:       ctx.strokeStyle = t.accent;
264:       ctx.lineWidth = 1.5;
265:       ctx.setLineDash([3, 3]);
266:       const dx = p.r === 1 ? 0 : p.r === 3 ? 0 : 0;
267:       ctx.beginPath(); ctx.moveTo(x - s * 0.7, y); ctx.lineTo(x + s * 0.7, y); ctx.stroke();
268:       ctx.setLineDash([]);
269:     } else if (p.t === 'boost') {
270:       ctx.fillStyle = t.body;
271:       ctx.beginPath(); ctx.roundRect(x - s / 2, y - s / 2, s, s, 4); ctx.fill();
272:       ctx.strokeStyle = t.glow;
273:       ctx.lineWidth = 2.5;
274:       ctx.beginPath(); ctx.moveTo(x - s * 0.2, y + s * 0.18); ctx.lineTo(x + s * 0.1, y - s * 0.18); ctx.lineTo(x + s * 0.35, y + s * 0.02); ctx.stroke();
275:     } else if (p.t === 'bounce') {
276:       ctx.fillStyle = t.body;
277:       ctx.beginPath(); ctx.roundRect(x - s / 2, y - s / 2, s, s, 4); ctx.fill();
278:       ctx.fillStyle = t.accent2;
279:       ctx.beginPath(); ctx.arc(x, y, s * 0.25, 0, Math.PI * 2); ctx.fill();
280:     } else if (p.t === 'start') {
281:       ctx.fillStyle = t.body;
282:       ctx.beginPath(); ctx.roundRect(x - s / 2, y - s / 2, s, s, 4); ctx.fill();
283:       ctx.fillStyle = '#5ce68d';
284:       ctx.beginPath(); ctx.arc(x, y - 2, s * 0.34, 0, Math.PI * 2); ctx.fill();
285:       ctx.fillStyle = '#0b2415';
286:       ctx.beginPath(); ctx.arc(x, y - 2, s * 0.14, 0, Math.PI * 2); ctx.fill();
287:     } else if (p.t === 'finish') {
288:       ctx.fillStyle = t.body;
289:       ctx.beginPath(); ctx.roundRect(x - s / 2, y - s / 2, s, s, 4); ctx.fill();
290:       ctx.strokeStyle = '#ffcf5a';
291:       ctx.lineWidth = 3;
292:       ctx.beginPath(); ctx.arc(x, y - 1, s * 0.33, 0, Math.PI * 2); ctx.stroke();
293:     } else if (p.t === 'checkpoint') {
294:       ctx.fillStyle = t.body;
295:       ctx.beginPath(); ctx.roundRect(x - s / 2, y - s / 2, s, s, 4); ctx.fill();
296:       ctx.fillStyle = t.accent;
297:       ctx.beginPath();
298:       ctx.moveTo(x, y - s * 0.34); ctx.lineTo(x + s * 0.22, y); ctx.lineTo(x, y + s * 0.34); ctx.lineTo(x - s * 0.22, y);
299:       ctx.closePath(); ctx.fill();
300:     } else {
301:       ctx.fillStyle = t.top;
302:       ctx.beginPath(); ctx.roundRect(x - s / 2, y - s / 2, s, s, 4); ctx.fill();
303:       ctx.fillStyle = `rgba(255,255,255,${0.04 + p.l * 0.03})`;
304:       ctx.beginPath(); ctx.roundRect(x - s / 2 + 1.5, y - s / 2 + 1.5, s - 3, s * 0.32, 3); ctx.fill();
305:     }
306:     if (p.l > 0) {
307:       ctx.strokeStyle = 'rgba(255,255,255,.24)';
308:       ctx.lineWidth = 1;
309:       ctx.beginPath();
310:       ctx.roundRect(x - s / 2, y - s / 2, s, s, 4);
311:       ctx.stroke();
312:     }
313:     void levelLift;
314:   }
315: 
316:   // vignette
317:   const v = ctx.createRadialGradient(w / 2, h / 2, h * 0.1, w / 2, h / 2, w * 0.65);
318:   v.addColorStop(0, 'rgba(0,0,0,0)');
319:   v.addColorStop(1, 'rgba(5,3,15,.55)');
320:   ctx.fillStyle = v;
321:   ctx.fillRect(0, 0, w, h);
322: }
