335: function makeMapCard(map, { custom = false } = {}) {
336:   const card = document.createElement('div');
337:   card.className = `map-card${custom ? ' has-actions' : ''}`;
338:   card.dataset.id = map.id;
339:   card.tabIndex = 0;
340:   card.setAttribute('role', 'button');
341:   const rank = store.bestMs(map.id) ? rankFor(map) : null;
342:   const best = store.bestMs(map.id);
343: 
344:   const thumb = document.createElement('div');
345:   thumb.className = 'map-thumb';
346:   const cv = document.createElement('canvas');
347:   thumb.appendChild(cv);
348:   const diff = document.createElement('div');
349:   diff.className = 'diff-badge';
350:   diff.innerHTML = `${difficultyLabel(map.difficulty)} `;
351:   for (let i = 0; i < 3; i++) {
352:     const dot = document.createElement('i');
353:     if (i < map.difficulty) dot.className = 'on';
354:     diff.appendChild(dot);
355:   }
356:   thumb.appendChild(diff);
357:   const par = document.createElement('div');
358:   par.className = 'par-badge';
359:   par.textContent = `PAR ${formatShort(map.par)}`;
360:   thumb.appendChild(par);
361: 
362:   if (custom) {
363:     const actions = document.createElement('div');
364:     actions.className = 'map-actions';
365:     const mk = (act, icon, label) => {
366:       const b = document.createElement('button');
367:       b.className = 'mini-btn';
368:       b.dataset.act = act;
369:       b.setAttribute('aria-label', label);
370:       b.title = label;
371:       b.innerHTML = icon;
372:       actions.appendChild(b);
373:     };
374:     mk('edit', icons.edit, 'Edit map');
375:     mk('share', icons.share, 'Share map');
376:     mk('delete', icons.trash, 'Delete map');
377:     card.appendChild(actions);
378:   }
379: 
380:   const info = document.createElement('div');
381:   info.className = 'map-info';
382:   const main = document.createElement('div');
383:   main.className = 'map-info-main';
384:   const h3 = document.createElement('h3');
385:   h3.textContent = map.name;
386:   const p = document.createElement('p');
387:   p.textContent = map.creatorBest && !best
388:     ? `Shared by ${map.creatorName || map.author} · target ${formatShort(map.creatorBest / 1000)}`
389:     : custom ? `By ${map.author || 'You'}${rank ? ` · rank #${rank}` : ''}` : map.tagline;
390:   main.append(h3, p);
391:   const bestEl = document.createElement('div');
392:   bestEl.className = 'map-best';
393:   bestEl.innerHTML = `<small>${best ? 'YOUR BEST' : map.creatorBest ? 'TARGET' : 'BEST'}</small><b class="${best ? '' : 'muted'}">${bestLabel(map)}</b>`;
394:   info.append(main, bestEl);
395: 
396:   card.append(thumb, info);
397:   requestAnimationFrame(() => drawMapThumb(cv, map));
398: 
399:   const start = () => {
400:     selectedPreviewId = map.id;
401:     startMap(map);
402:   };
403:   card.addEventListener('click', (ev) => {
404:     const act = ev.target.closest('[data-act]');
405:     if (act) {
406:       ev.stopPropagation();
407:       handleMapAction(act.dataset.act, map);
408:       return;
409:     }
410:     start();
411:   });
412:   card.addEventListener('keydown', (ev) => {
413:     if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); start(); }
414:   });
415:   if (!coarse) {
416:     card.addEventListener('pointerenter', () => {
417:       clearTimeout(previewTimer);
418:       previewTimer = setTimeout(() => {
419:         if (game.mode !== 'preview' || currentTab === 'paused') return;
420:         if (selectedPreviewId !== map.id) {
421:           selectedPreviewId = map.id;
422:           game.previewMap(map);
423:         }
424:       }, 170);
425:     });
426:   }
427:   return card;
428: }
