545: function startMap(map, opts = {}) {
546:   if (!map) return;
547:   const test = !!opts.test;
548:   const fromBuilder = !!opts.fromBuilder;
549:   currentRaceMap = map;
550:   currentRaceIsTest = test;
551:   testOrigin = fromBuilder;
552:   currentRaceForBuilder = fromBuilder;
553:   keys.clear();
554:   resetJoystick();
555:   hideToast();
556:   $('split-toast').classList.remove('show');
557:   $('hint-banner').classList.remove('show');
558:   showRaceHud(map);
559:   showCountdownShell();
560: 
561:   const record = test ? null : store.record(map.id);
562:   const ghostPath = (!test && store.data.settings.ghost && record?.ghost && record.ghost.length > 1)
563:     ? record.ghost : null;
564:   const ghostPars = ghostPath ? record.best : null;
565: 
566:   if (ghostPath) {
567:     $('ghost-badge').textContent = `GHOST ${formatShort(record.best / 1000)}`;
568:     $('ghost-badge').classList.remove('is-hidden');
569:   }
570:   $('hud-cp').textContent = 'CP 0/0';
571:   audio.unlock();
572:   audio.uiOpen();
573:   game.startRace(map, {
574:     ghostPath,
575:     bestSplits: record?.splits || null,
576:     test,
577:     record: !test,
578:     ghost: store.data.settings.ghost,
579:   });
580:   $('hud-cp').textContent = `CP 0/${game.checkpoints.length}`;
581:   if (ghostPars) $('ghost-badge').textContent = `GHOST ${formatShort(ghostPars / 1000)}`;
582: 
583:   clearTimeout(hintTimer);
584:   $('hint-banner').textContent = mapHasStartFinish(map)
585:     ? 'Follow the course · reach the finish gate'
586:     : 'Reach the glowing gate';
587:   $('hint-banner').classList.add('show');
588:   hintTimer = setTimeout(() => $('hint-banner').classList.remove('show'), 4200);
589: }
590: 
591: function restartCurrentRace() {
592:   if (!currentRaceMap) return;
593:   hidePause();
594:   startMap(currentRaceMap, { test: currentRaceIsTest, fromBuilder: currentRaceForBuilder });
595: }
596: 
597: function quitCurrentRace() {
598:   const fromBuilder = testOrigin;
599:   game.quitRace();
600:   hidePause();
601:   hideCountdown();
602:   if (fromBuilder) {
603:     resumeBuilderFromTest();
604:   } else {
605:     showMaps(currentTab);
606:   }
607: }
608: 
609: function handleFinish(result) {
610:   const map = currentRaceMap;
611:   if (!map) return;
612:   keys.clear();
613:   resetJoystick();
614:   const prevBest = store.bestMs(map.id);
615:   let isBest = false;
616:   if (!result.test) {
617:     isBest = store.saveBest(map.id, result.time, result.recording, result.splits);
618:   }
619:   lastResult = { map, result, prevBest, isBest };
620:   hideCountdown();
621:   $('split-toast').classList.remove('show');
622:   $('hint-banner').classList.remove('show');
623:   showResult();
624:   renderResult();
625:   const medal = result.test ? 'finisher' : medalFor(result.time, map.par);
626:   if (!result.test && (isBest || medal === 'gold')) confetti();
627: }
628: 
629: function nextCourse() {
630:   if (testOrigin) {
631:     resumeBuilderFromTest();
632:     return;
633:   }
634:   if (!currentRaceMap) return openMaps();
635:   if (currentRaceIsTest) return resumeBuilderFromTest();
636:   const idx = currentOfficialIndex(currentRaceMap);
637:   if (idx >= 0 && idx < BUILTIN_MAPS.length - 1) {
638:     selectedPreviewId = BUILTIN_MAPS[idx + 1].id;
639:     startMap(BUILTIN_MAPS[idx + 1]);
640:     return;
641:   }
642:   const customs = store.customMaps();
643:   const cidx = customs.findIndex((m) => m.id === currentRaceMap.id);
644:   if (cidx >= 0 && cidx < customs.length - 1) {
645:     startMap(customs[cidx + 1]);
646:     return;
647:   }
648:   showMaps(currentTab);
649: }
650: 
651: function renderResult() {
652:   if (!lastResult) return;
653:   const { map, result, prevBest, isBest } = lastResult;
654:   const test = !!result.test;
655:   const medal = test ? 'finisher' : medalFor(result.time, map.par);
656:   const medalEl = $('medal');
657:   medalEl.className = `medal ${medal}`;
658:   $('medal-label').textContent = test ? 'STUDIO' : medal === 'finisher' ? 'CLEAR' : medal.toUpperCase();
659:   $('result-eyebrow').textContent = test ? `STUDIO TEST · ${map.name.toUpperCase()}` : `${map.name.toUpperCase()} · RUN COMPLETE`;
660: 
661:   const rank = test ? null : rankFor(map);
662:   let title = 'Course cleared.';
663:   if (test) title = 'Studio test complete.';
664:   else if (isBest && prevBest) title = 'New personal best.';
665:   else if (isBest) title = 'First run logged.';
666:   else if (rank === 1) title = 'Course record.';
667:   else if (rank && rank <= 3) title = 'Podium finish.';
668:   else if (medal === 'gold') title = 'Untouchable.';
669:   $('result-title').textContent = title;
670:   $('result-time').textContent = formatTime(result.time);
671: 
672:   const deltas = $('result-deltas');
673:   deltas.innerHTML = '';
674:   const pill = (text, cls = '') => {
675:     const span = document.createElement('span');
676:     span.className = `pill ${cls}`;
677:     span.textContent = text;
678:     deltas.appendChild(span);
679:   };
680:   if (test) {
681:     pill('Times are not saved in the studio');
682:     pill(`PAR ${formatTime(map.par * 1000, false)}`);
683:   } else {
684:     if (prevBest && isBest) pill(`NEW BEST ${formatDelta(result.time - prevBest)}`, 'good');
685:     else if (prevBest) pill(`${formatDelta(result.time - prevBest)} off your best`, 'bad');
686:     else pill('FIRST TIME LOGGED', 'good');
687:     pill(medal === 'gold' ? 'GOLD PACE' : medal === 'silver' ? 'SILVER PACE' : 'PAR ' + formatTime(map.par * 1000, false), medal === 'gold' ? 'good' : '');
688:     if (rank) pill(`RANK #${rank}`, rank <= 3 ? 'good' : '');
689:   }
690: 
691:   const board = $('result-board');
692:   board.innerHTML = '';
693:   if (!test) {
694:     const rows = leaderboardFor(map);
695:     const yourIndex = rows.findIndex((r) => r.you);
696:     const top = rows.slice(0, 5);
697:     if (yourIndex > 4) top.push(rows[yourIndex]);
698:     const titleRow = document.createElement('div');
699:     titleRow.className = 'board-title';
700:     titleRow.innerHTML = '<span>CLUB RANKING</span><span>LOCAL</span>';
701:     board.appendChild(titleRow);
702:     top.forEach((row) => {
703:       const actualRank = rows.indexOf(row) + 1;
704:       const el = document.createElement('div');
705:       el.className = `board-row${row.you ? ' you' : ''}`;
706:       const rankEl = document.createElement('span');
707:       rankEl.className = 'rank';
708:       rankEl.textContent = String(actualRank).padStart(2, '0');
709:       const nameEl = document.createElement('span');
710:       nameEl.className = 'name';
711:       const av = document.createElement('span');
712:       av.className = 'avatar';
713:       av.style.background = row.color || '#ffb86b';
714:       av.textContent = initials(row.name);
715:       nameEl.append(av, document.createTextNode(row.name));
716:       const timeEl = document.createElement('span');
717:       timeEl.className = 'time';
718:       timeEl.textContent = formatShort(row.time);
719:       el.append(rankEl, nameEl, timeEl);
720:       board.appendChild(el);
721:     });
722:     if (rows.length === 0) {
723:       const empty = document.createElement('div');
724:       empty.className = 'empty-state';
725:       empty.textContent = 'No times on this board yet.';
726:       board.appendChild(empty);
727:     }
728:   }
729: 
730:   $('btn-result-retry').textContent = test ? 'TEST AGAIN' : 'RACE AGAIN';
731:   const nextBtn = $('btn-result-next');
732:   if (test) {
733:     nextBtn.textContent = 'BACK TO STUDIO';
734:     nextBtn.classList.remove('is-hidden');
735:   } else {
736:     const idx = currentOfficialIndex(map);
737:     const customs = store.customMaps();
738:     const cidx = customs.findIndex((m) => m.id === map.id);
739:     const hasNext = (idx >= 0 && idx < BUILTIN_MAPS.length - 1) || (cidx >= 0 && cidx < customs.length - 1);
740:     nextBtn.classList.toggle('is-hidden', !hasNext);
741:     nextBtn.textContent = 'NEXT COURSE';
742:   }
743:   $('btn-result-exit').textContent = test ? 'QUIT TO MAPS' : 'BACK TO MAPS';
744:   const shareWrap = $('result-share');
745:   shareWrap.classList.toggle('is-hidden', test || !map.id.startsWith('u-'));
746: }
