793: function syncBuilderUI() {
794:   if (!builderState) return;
795:   const map = builderState.map;
796:   $('builder-name').textContent = map.name || 'Untitled Course';
797:   $('level-value').textContent = game.builder.level;
798:   const checkpoints = map.pieces.filter((p) => p.t === 'checkpoint').length;
799:   const hasStart = map.pieces.some((p) => p.t === 'start');
800:   const hasFinish = map.pieces.some((p) => p.t === 'finish');
801:   const meta = $('builder-meta');
802:   meta.innerHTML = '';
803:   if (!hasStart || !hasFinish) {
804:     const warn = document.createElement('span');
805:     warn.className = 'builder-warn';
