809:   meta.append(document.createTextNode(`${map.pieces.length} pieces · ${checkpoints} checkpoint${checkpoints === 1 ? '' : 's'} · PAR ≈ ${formatTime(estimatedPar(map.pieces) * 1000, false)}`));
810:   for (const btn of document.querySelectorAll('.piece-btn')) {
811:     btn.classList.toggle('is-active', btn.dataset.piece === game.builder.tool);
812:   }
813:   const p = PIECES.find((x) => x.id === game.builder.tool);
814:   $('builder-hint').textContent = (p?.hint || 'Tap the grid to place.') + ' · drag to orbit';
815:   $('btn-builder-save').classList.toggle('attention', builderState.dirty);
