823: function validateBuilder(showMessage = true) {
824:   if (!builderState) return false;
825:   const pieces = builderState.map.pieces;
826:   if (!pieces.some((p) => p.t === 'start') || !pieces.some((p) => p.t === 'finish')) {
827:     if (showMessage) showToast('Add a start pad and a finish gate first.');
828:     return false;
829:   }
830:   if (pieces.length < 3) {
831:     if (showMessage) showToast('Add a little more course first.');
832:     return false;
833:   }
834:   return true;
835: }
