283:       sunDir: { value: new THREE.Vector3(0.4, 0.45, 0.3).normalize() },
284:     };
285:     const geo = new THREE.SphereGeometry(320, 32, 20);
286:     const mat = new THREE.ShaderMaterial({
287:       uniforms: this.skyUniforms,
288:       side: THREE.BackSide,
289:       depthWrite: false,
290:       fog: false,
291:       vertexShader: `
292:         varying vec3 vWorld;
293:         void main() {
294:           vec4 wp = modelMatrix * vec4(position, 1.0);
295:           vWorld = wp.xyz;
296:           gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
297:         }
298:       `,
299:       fragmentShader: `
300:         uniform vec3 top; uniform vec3 mid; uniform vec3 bottom;
301:         uniform vec3 sunColor; uniform vec3 sunDir;
302:         varying vec3 vWorld;
303:         void main() {
304:           vec3 d = normalize(vWorld);
305:           float h = d.y;
306:           vec3 col = mix(bottom, mid, smoothstep(-0.08, 0.22, h));
307:           col = mix(col, top, smoothstep(0.16, 0.78, h));
308:           float sd = max(dot(d, normalize(sunDir)), 0.0);
309:           col += sunColor * pow(sd, 220.0) * 2.2;
310:           col += sunColor * pow(sd, 9.0) * 0.24;
