375:   makeMat(color, opts = {}) {
376:     const key = `${color}|${opts.emissive || 0}|${opts.roughness ?? 0.55}|${opts.metalness ?? 0.02}|${opts.opacity ?? 1}|${opts.side || 0}|${opts.flat ? 1 : 0}`;
377:     if (this.materials.has(key)) return this.materials.get(key);
378:     const mat = new THREE.MeshStandardMaterial({
379:       color,
380:       roughness: opts.roughness ?? 0.55,
381:       metalness: opts.metalness ?? 0.02,
382:       emissive: opts.emissive || 0x000000,
383:       emissiveIntensity: opts.emissiveIntensity ?? 1,
384:       transparent: (opts.opacity ?? 1) < 1,
385:       opacity: opts.opacity ?? 1,
386:       side: opts.side || THREE.FrontSide,
387:       flatShading: !!opts.flat,
388:       envMapIntensity: opts.envMapIntensity ?? 0.18,
389:     });
