402:   boxGeo(w, h, d, r = 0.09, seg = 2) {
403:     const key = `${w.toFixed(2)}|${h.toFixed(2)}|${d.toFixed(2)}|${r}|${seg}`;
404:     if (this.geometries.has(key)) return this.geometries.get(key);
