446:   setLightingBounds(bounds, padding = 13) {
447:     const t = this.theme;
448:     if (!t) return;
449:     const cx = ((bounds.minX + bounds.maxX) / 2) * CELL;
450:     const cz = ((bounds.minZ + bounds.maxZ) / 2) * CELL;
451:     const cy = ((bounds.minL + bounds.maxL) / 2) * STEP;
452:     const sx = (bounds.maxX - bounds.minX + 1) * CELL;
453:     const sz = (bounds.maxZ - bounds.minZ + 1) * CELL;
454:     const size = clamp(Math.max(sx, sz) * 0.72 + padding, 22, 74);
455:     const cam = this.dir.shadow.camera;
456:     cam.left = -size; cam.right = size; cam.top = size; cam.bottom = -size;
457:     cam.updateProjectionMatrix();
458:     this.dir.target.position.set(cx, cy, cz);
459:     this.dir.position.set(cx + 26, cy + 40, cz + 22);
460:     this.rim.position.set(cx - 25, cy + 14, cz - 22);
461:     this.skyUniforms.sunDir.value.set(0.45, 0.5, 0.36).normalize();
462:   }
