662:       isle.add(top, bottom);
663:       isle.position.set(x, y, z);
664:       g.add(isle);
665:       if (random() > 0.35) {
666:         const crystal = new THREE.Mesh(
667:           new THREE.OctahedronGeometry(0.35 * scale, 0),
668:           new THREE.MeshStandardMaterial({ color: t.accent, emissive: t.accent, emissiveIntensity: 1.7, roughness: 0.25 }),
