955:   getBoostTexture() {
956:     if (this.boostTexture) return this.boostTexture;
957:     const c = document.createElement('canvas');
958:     c.width = 256; c.height = 256;
959:     const ctx = c.getContext('2d');
960:     ctx.clearRect(0, 0, 256, 256);
961:     ctx.strokeStyle = 'white';
962:     ctx.lineWidth = 26;
963:     ctx.lineJoin = 'round';
964:     ctx.lineCap = 'round';
965:     for (let i = 0; i < 3; i++) {
966:       const y = 76 + i * 52;
967:       ctx.beginPath();
968:       ctx.moveTo(70, y);
969:       ctx.lineTo(128, y - 34);
970:       ctx.lineTo(186, y);
971:       ctx.stroke();
972:     }
973:     const tex = new THREE.CanvasTexture(c);
974:     tex.colorSpace = THREE.SRGBColorSpace;
975:     this.boostTexture = tex;
976:     return tex;
977:   }
