271: export function courseBounds(pieces) {
272:   let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, minL = 0, maxL = 0;
273:   for (const p of pieces) {
274:     minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
275:     minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
276:     minL = Math.min(minL, p.l); maxL = Math.max(maxL, p.l);
277:   }
278:   if (!pieces.length) return { minX: -2, maxX: 2, minZ: -2, maxZ: 2, minL: 0, maxL: 0 };
279:   return { minX, maxX, minZ, maxZ, minL, maxL };
280: }
