282: export function estimatedPar(pieces) {
283:   const b = courseBounds(pieces);
284:   const span = (b.maxX - b.minX + b.maxZ - b.minZ + 2) * 2.3;
285:   return Math.max(12, Math.round(span + pieces.length * 0.22));
286: }
